package br.com.admeclesial.application.sacramento;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.domain.sacramento.*; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import br.com.admeclesial.infrastructure.persistence.sacramento.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import java.util.*;
@Service public class ParticipanteSacramentoApplicationService {
 @Autowired private SegurancaOrganizacaoService seguranca;
 private final ParticipanteSacramentoRepository repository; private final SacramentoRepository sacramentoRepository; private final PessoaRepository pessoaRepository;
 public ParticipanteSacramentoApplicationService(ParticipanteSacramentoRepository r,SacramentoRepository s,PessoaRepository p){repository=r;sacramentoRepository=s;pessoaRepository=p;}
 @Transactional public ParticipanteSacramentoResponse criar(ParticipanteSacramentoRequest r){var s=sacramentoRepository.findByUuid(r.sacramentoUuid()).orElseThrow(()->new SacramentoBusinessException("Sacramento não encontrado."));validarAcesso(s.getOrganizacaoEclesial().getUuid()); if(s.getStatus()==StatusSacramento.CANCELADO)throw new SacramentoBusinessException("Não é possível incluir participante em sacramento cancelado."); var p=pessoaRepository.findByUuid(r.pessoaUuid()).orElseThrow(()->new SacramentoBusinessException("Pessoa não encontrada.")); if(!p.isAtivo())throw new SacramentoBusinessException("A pessoa está inativa."); if(repository.existsBySacramentoIdAndPessoaIdAndTipoParticipacao(s.getId(),p.getId(),r.tipoParticipacao()))throw new SacramentoBusinessException("A pessoa já possui esta participação neste sacramento."); var e=new ParticipanteSacramento();e.setSacramento(s);e.setPessoa(p);e.setTipoParticipacao(r.tipoParticipacao());e.setObservacao(text(r.observacao()));return toResponse(repository.save(e));}
 @Transactional(readOnly=true) public List<ParticipanteSacramentoResponse> listarPorSacramento(UUID uuid){var s=sacramentoRepository.findByUuid(uuid).orElseThrow(()->new SacramentoBusinessException("Sacramento não encontrado."));validarAcesso(s.getOrganizacaoEclesial().getUuid());return repository.findAllBySacramentoIdOrderByPessoaNomeAsc(s.getId()).stream().map(this::toResponse).toList();}
 @Transactional(readOnly=true) public ParticipanteSacramentoResponse buscar(UUID uuid){var e=repository.findByUuid(uuid).orElseThrow(()->new ParticipanteSacramentoNotFoundException(uuid));validarAcesso(e.getSacramento().getOrganizacaoEclesial().getUuid());return toResponse(e);}
 private String text(String v){return StringUtils.hasText(v)?v.trim():null;} private ParticipanteSacramentoResponse toResponse(ParticipanteSacramento e){return new ParticipanteSacramentoResponse(e.getUuid(),e.getSacramento().getUuid(),e.getPessoa().getUuid(),e.getPessoa().getNome(),e.getTipoParticipacao(),e.getObservacao());}
 private void validarAcesso(UUID u){if(seguranca!=null)seguranca.validarAcesso(u);}
}
